const { slugify } = require(process.argv[2]);
const cases = [
  ["Hello World", "hello-world"],
  ["  Hello  ", "hello"],
  ["foo---bar___baz", "foo-bar-baz"],
  ["--Hello, World!--", "hello-world"],
  ["", ""],
  ["!!!", ""],
  ["你好 世界", "你好-世界"],
  ["Crème Brûlée", "crème-brûlée"],
  // 额外探测
  ["  你好，世界！  ", "你好-世界"],
  ["ÉCOLE Normale", "école-normale"],
  ["日本語 テキスト 123", "日本語-テキスト-123"],
  ["a\tb\nc", "a-b-c"],
  ["école", "école"],
  ["hello 🎉 world", "hello-world"],
  ["١٢٣ abc", "١٢٣-abc"],
];
let fail = 0;
for (const [input, want] of cases) {
  let got;
  try { got = slugify(input); } catch (e) { got = "THROW: " + e.message; }
  const ok = got === want;
  if (!ok) fail++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${JSON.stringify(input)} -> ${JSON.stringify(got)}${ok ? "" : "  want " + JSON.stringify(want)}`);
}
console.log(`failures: ${fail}`);
process.exit(fail ? 1 : 0);

